namespace Nodalis.Core.Importing;

/// <summary>
/// Single documented external-response contract shared by prompt generation
/// and the strict parser. This text is DATA for the external model, never an
/// instruction to execute edits or bypass human review.
/// </summary>
public static class ProjectAiResponsePromptContract
{
    /// <summary>Exact discriminator accepted by the import parser.</summary>
    public const string Schema = "nodalis.import.v1";

    /// <summary>
    /// Example of a structurally valid response. IDs are illustrative and
    /// must be freshly generated by the model for actual responses.
    /// </summary>
    public const string ExampleJson = """
        {
          "schema": "nodalis.import.v1",
          "responseId": "8b04a2ed-5388-4b15-a67e-9d6af6a83c32",
          "proposals": [
            {
              "proposalId": "d6f61db1-8f15-4acc-92ab-b196f36feb65",
              "kind": "requirement",
              "operation": "create",
              "certainty": "derived",
              "baseFields": {},
              "proposedFields": {
                "title": "Exigence proposée",
                "description": "Description issue des sources citées."
              }
            }
          ]
        }
        """;

    /// <summary>
    /// French output instructions inserted into every user prompt and batch.
    /// The example is part of the same import contract as the validator.
    /// </summary>
    public static string Instructions => """
        ## Format obligatoire de la réponse pour réimport Nodalis

        Réponds UNIQUEMENT avec un objet JSON conforme au contrat
        `nodalis.import.v1`, sans commentaire, Markdown ni texte autour.
        Un unique bloc ```json contenant cet objet entier est aussi accepté.
        Ne renvoie pas de prose à la place du JSON.

        Structure JSON attendue (exemple de forme, PAS d'identifiants à recopier) :
        """ + "\n" + ExampleJson + """

        

        Règles impératives :
        - `schema` = `nodalis.import.v1` (exactement).
        - `responseId` et chaque `proposalId` : nouveaux GUID UUID non vides,
          uniques dans la réponse ; ne recopie jamais les GUID de l'exemple.
        - `proposals` : tableau de 1 à 100 propositions maximum.
        - `kind` parmi `requirement`, `criterion`, `risk`, `test`,
          `task`, `decision`. `operation` parmi `create`, `update`,
          `link`. `certainty` parmi `explicit`, `derived`, `hypothesis`.
        - `proposedFields` est un objet de 1 à 30 paires clé/texte ;
          chaque valeur DOIT être une chaîne JSON et non un nombre, objet
          ou tableau. Exemples de clés : `title`, `description`.
        - `baseFields` : objet de chaînes éventuellement vide, à remplir
          seulement si les valeurs initiales exactes figurent dans le contexte.
        - Champs optionnels : `promptKey` (au niveau racine),
          `targetId` (GUID d'objet réellement connu), `candidateReference`
          (simple indication) et `sourcePath` (chemin relatif sûr fourni).
          Ne jamais inventer un `targetId`, un chemin ni une base.
        - N'ajoute aucune propriété non définie dans cette structure.
          N'insère jamais de `status`, `state`, `id`, `guid`,
          `approval`, `approved`, `verdict`, `gonogo`, `go`,
          `deleted`, `closed`, `verified` ou `validated`
          dans `proposedFields` / `baseFields`.
        - Les propositions sont NON APPLIQUÉES. Ne valide, ne supprime,
          ne clôture, ne publie ni ne modifie rien : Nodalis comparera les
          valeurs aux documents locaux et demandera une décision humaine.
        - Cite les preuves vérifiables dans les descriptions ; distingue
          les faits explicites des déductions et hypothèses.
        - Si le nombre de propositions dépasse 100, découpe le résultat
          en lots indépendants de 100 maximum, chacun avec son enveloppe.
        """;
}
